 1	//! A small task tracker.
 2	
 3	use std::env;
 4	use std::fs;
 5	
 6	struct Task {
 7	    id: i64,
 8	    title: String,
 9	    done: bool,
10	}
11	
12	fn find(tasks: &mut [Task], id: i64) -> Option<&mut Task> {
13	    tasks.iter_mut().find(|task| task.id == id)
14	}
15	
16	fn main() {
17	    let path = env::args().nth(1).expect("a command file");
18	    let text = fs::read_to_string(&path).expect("a readable command file");
19	    let mut tasks: Vec<Task> = Vec::new();
20	    let mut next_id = 1;
21	
22	    for line in text.trim_end_matches('\n').split('\n') {
23	        if line.is_empty() {
24	            continue;
25	        }
26	        let (command, rest) = match line.split_once(' ') {
27	            Some((command, rest)) => (command, rest),
28	            None => (line, ""),
29	        };
30	
31	        if command == "add" {
32	            tasks.push(Task { id: next_id, title: rest.to_string(), done: false });
33	            println!("added {}", next_id);
34	            next_id += 1;
35	        } else if command == "done" {
36	            let id: i64 = rest.parse().expect("a task id");
37	            match find(&mut tasks, id) {
38	                None => println!("no such task {}", id),
39	                Some(task) => {
40	                    task.done = true;
41	                    println!("done {}", id);
42	                }
43	            }
44	        } else if command == "list" {
45	            for task in tasks.iter().filter(|task| !task.done) {
46	                println!("{} {}", task.id, task.title);
47	            }
48	        }
49	    }
50	}
