input.command:
python3 - <<'EOF'
p='src/main.rs'
s=open(p).read()
s=s.replace("""    done: bool,
}""","""    done: bool,
    priority: u8,
}""")
s=s.replace("""fn main() {""","""/// Tasks in listing order: priority ascending, then id ascending.
fn ordered(tasks: &[Task]) -> Vec<&Task> {
    let mut sorted: Vec<&Task> = tasks.iter().collect();
    sorted.sort_by_key(|task| (task.priority, task.id));
    sorted
}

fn main() {""")
s=s.replace("""        if line.is_empty() {""","""        if line.trim().is_empty() {""")
s=s.replace("""done: false });""","""done: false, priority: 5 });""")
s=s.replace("""        } else if command == "list" {
            for task in tasks.iter().filter(|task| !task.done) {
                println!("{} {}", task.id, task.title);
            }
        }""","""        } else if command == "prio" {
            let (id_text, p_text) = rest.split_once(' ').unwrap_or((rest, ""));
            let task = id_text.parse().ok().and_then(|id| find(&mut tasks, id));
            match task {
                None => println!("no such task {}", id_text),
                Some(task) => match p_text.parse::<u8>() {
                    Ok(p) if p_text.len() == 1 && p <= 9 => {
                        task.priority = p;
                        println!("prio {} {}", task.id, p);
                    }
                    _ => println!("bad priority {}", p_text),
                },
            }
        } else if command == "list" {
            if rest == "all" {
                for task in ordered(&tasks) {
                    let mark = if task.done { 'x' } else { '-' };
                    println!("{} {} {}", mark, task.id, task.title);
                }
            } else {
                for task in ordered(&tasks).into_iter().filter(|task| !task.done) {
                    println!("{} {}", task.id, task.title);
                }
            }
        } else {
            println!("? {}", command);
        }""")
open(p,'w').write(s)
EOF
cargo fmt 2>/dev/null; cargo clippy --all-targets 2>&1 | tail -3
cat > /tmp/t1.txt <<'EOF'
add buy milk
add write report now

add call mom
list
prio 2 1
prio 9 3
prio 3 x
prio 3 10
prio 1 5
done 1
done 7
list
list all
frobnicate this thing
prio 3 0
list all
EOF
cargo run -q -- /tmp/t1.txt

